// halo-workspace-path-v1: lexical Windows workspace identity; stored headers stay untouched.
import {win32 as haloWindowsPath} from "node:path";
function workspaceKey(value, platform = process.platform) {
  // Only fully qualified Windows paths: never resolve a relative path or fold case.
  if (platform !== 'win32' || typeof value !== 'string' || !(/^[a-zA-Z]:[\\/]/.test(value) || /^[\\/]{2}[^\\/]/.test(value))) return value;
  const normalized = haloWindowsPath.normalize(value);
  const root = haloWindowsPath.parse(normalized).root;
  return normalized.length > root.length ? normalized.replace(/[\\/]+$/, '') : normalized;
}

